import json
import asyncio
from typing import AsyncGenerator, List, Optional, Dict, Any
from app.providers.base import LLMProvider, LLMChunk
from app.schemas import InternalMessage, ToolCall


class MockProvider(LLMProvider):
    """Zero-key offline mock provider for local testing and tool loop verification."""

    DEFAULT_RESPONSE = (
        "### Aether AI Response\n\n"
        "This response is generated by the local **MockProvider**.\n\n"
        "Key highlights:\n"
        "- **Low idle resource usage**: Zero external API dependencies or background workers.\n"
        "- **Full streaming SSE support**: Emits token-by-token events with realistic cadence.\n"
        "- **Resilient**: Fully honors client disconnects and cancels in-flight work immediately.\n"
    )

    async def stream_chat(
        self,
        messages: List[InternalMessage],
        model: str,
        temperature: float,
        max_output_tokens: int,
        system_prompt: str,
        tools: Optional[List[Dict[str, Any]]] = None,
    ) -> AsyncGenerator[LLMChunk, None]:
        # Check if tools are active and user requested a tool via mock command
        if tools and messages:
            # Check if there are already tool response messages in the tail
            tool_msgs = [m for m in messages if m.role == "tool"]
            if tool_msgs:
                # Tools have already executed! Stream the final summary of the tool results
                yield LLMChunk(is_thinking=True, thought="Synthesizing tool outputs into final answer...")
                await asyncio.sleep(0.04)

                summary_parts = [f"- **{m.name or 'tool'}**: {m.content[:80]}" for m in tool_msgs]
                response_text = (
                    "### Tool Execution Summary\n\n"
                    "The following tool results were processed:\n"
                    + "\n".join(summary_parts)
                    + "\n\nAll tools executed successfully."
                )
                words = response_text.split(" ")
                for i, word in enumerate(words):
                    token = word if i == 0 else " " + word
                    yield LLMChunk(token=token)
                    await asyncio.sleep(0.015)
                return

            # Check if the last user message requests a tool call
            last_msg = messages[-1]
            content = last_msg.content.strip()

            if content.startswith("/tool "):
                # Syntax: /tool <name> <json_args>
                parts = content[6:].split(" ", 1)
                tool_name = parts[0]
                args_str = parts[1] if len(parts) > 1 else "{}"
                try:
                    args = json.loads(args_str)
                except Exception:
                    args = {}

                yield LLMChunk(
                    tool_calls=[
                        ToolCall(
                            id="mock_call_1",
                            name=tool_name,
                            arguments=args,
                        )
                    ]
                )
                return

            if content.startswith("/tools "):
                # Syntax: /tools <name1> <json1> | <name2> <json2>
                calls_spec = content[7:].split("|")
                tool_calls = []
                for idx, spec in enumerate(calls_spec):
                    spec = spec.strip()
                    parts = spec.split(" ", 1)
                    name = parts[0]
                    args_str = parts[1] if len(parts) > 1 else "{}"
                    try:
                        args = json.loads(args_str)
                    except Exception:
                        args = {}
                    tool_calls.append(
                        ToolCall(id=f"mock_call_{idx+1}", name=name, arguments=args)
                    )

                if tool_calls:
                    yield LLMChunk(tool_calls=tool_calls)
                    return

        # Normal text generation
        yield LLMChunk(is_thinking=True, thought="Synthesizing response from conversation context...")
        await asyncio.sleep(0.04)

        last_user_msg = messages[-1].content if messages else "Hello"
        response_text = f"Received your query: *\"{last_user_msg[:60]}...\"*\n\n{self.DEFAULT_RESPONSE}"

        words = response_text.split(" ")
        for i, word in enumerate(words):
            token = word if i == 0 else " " + word
            yield LLMChunk(token=token)
            await asyncio.sleep(0.015)

    async def complete_chat(
        self,
        messages: List[InternalMessage],
        model: str,
        temperature: float,
        max_output_tokens: int,
        system_prompt: str,
        tools: Optional[List[Dict[str, Any]]] = None,
    ) -> str:
        last_user_msg = messages[-1].content if messages else "Hello"
        return f"Received your query: *\"{last_user_msg[:60]}...\"*\n\n{self.DEFAULT_RESPONSE}"
